np=__import__("numpy")
def _tree(value):
    if isinstance(value, np.ndarray):
        return [float(value.ndim), *[float(x) for x in value.shape], *value.astype(float).ravel().tolist()]
    if isinstance(value, (tuple, list)):
        out = [float(len(value))]
        for item in value:
            out.extend(_tree(item))
        return out
    return [float(value)]
assert np.allclose(_tree(generate_oci_neb_panel()), target)

